{"command":"cat <<'EOF' > main.py
#!/usr/bin/env python3
import sys, os, time, json, random, subprocess, threading, argparse

def rle_encode(owners):
    res = []
    if not owners: return ""
    count = 1
    curr = owners[0]
    for i in range(1, len(owners)):
        if owners[i] == curr:
            count += 1
        else:
            res.extend([str(count), str(curr)])
            curr = owners[i]
            count = 1
    res.extend([str(count), str(curr)])
    return " ".join(res) + " "

def parse_moves(line, width, height):
    moves = [[0 for _ in range(width)] for _ in range(height)]
    parts = line.strip().split()
    i = 0
    while i < len(parts):
        try:
            x = int(parts[i])
            y = int(parts[i+1])
            d = int(parts[i+2])
            if 0 <= x < width and 0 <= y < height and 0 <= d <= 4:
                moves[y][x] = d
            i += 3
        except:
            break
    return moves

class Bot:
    def __init__(self, cmd, idx):
        self.cmd = cmd
        self.idx = idx
        self.process = subprocess.Popen(cmd, shell=True, stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True, bufsize=1)
        self.name = f"Bot #{idx}"
        self.alive = True
        self.timeout = False
        self.rank = 0
        self.last_alive = -1

    def send(self, msg):
        if not self.alive: return
        try:
            self.process.stdin.write(msg)
            self.process.stdin.flush()
        except:
            self.alive = False

    def get_line(self, t):
        if not self.alive: return ""
        res = [""]
        def read():
            try:
                res[0] = self.process.stdout.readline()
            except:
                pass
        th = threading.Thread(target=read)
        th.daemon = True
        th.start()
        th.join(t)
        if th.is_alive():
            self.alive = False
            self.timeout = True
            return ""
        if not res[0]:
            self.alive = False
        return res[0]

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-i', '--replaydirectory', type=str, default='.')
    parser.add_argument('-s', '--seed', type=int, default=None)
    parser.add_argument('-d', '--dimensions', type=str, default='30 30')
    parser.add_argument('-n', '--nplayers', type=int, default=None)
    parser.add_argument('-r', '--noreplay', action='store_true')
    parser.add_argument('-t', '--timeout', action='store_true')
    parser.add_argument('-o', '--override', action='store_true')
    parser.add_argument('-q', '--quiet', action='store_true')
    parser.add_argument('--version', action='store_true')
    parser.add_argument('-h', '--help', action='store_true')

    args, unknown = parser.parse_known_args()

    if args.version:
        print("\n./executable  version: 1.2\n")
        sys.exit(0)
    if args.help:
        print("USAGE: \n\n   ./executable  [-i <path to directory>] [-s <positive integer>] [-d <a\n                 string containing two space-seprated positive integers>]\n                 [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version]\n                 [-h] <Array of strings> ...\n\nWhere: \n\n   -i <path to directory>,  --replaydirectory <path to directory>\n     The path to directory for replay output.\n\n   -s <positive integer>,  --seed <positive integer>\n     The seed for the map generator.\n\n   -d <a string containing two space-seprated positive integers>, \n      --dimensions <a string containing two space-seprated positive\n      integers>\n     The dimensions of the map.\n\n   -n <{1,2,3,4,5,6}>,  --nplayers <{1,2,3,4,5,6}>\n     Create a map that will accommodate n players [SINGLE PLAYER MODE\n     ONLY].\n\n   -r,  --noreplay\n     Turns off the replay generation.\n\n   -t,  --timeout\n     Causes game environment to ignore timeouts (give all bots infinite\n     time).\n\n   -o,  --override\n     Overrides player-sent names using cmd args [SERVER ONLY].\n\n   -q,  --quiet\n     Runs game in quiet mode, producing machine-parsable output.\n\n   --,  --ignore_rest\n     Ignores the rest of the labeled arguments following this flag.\n\n   --version\n     Displays version information and exits.\n\n   -h,  --help\n     Displays usage information and exits.\n\n   <Array of strings>  (accepted multiple times)\n     Start commands for bots.\n\n\n   Halite Game Environment\n")
        sys.exit(0)

    bot_cmds = unknown
    if '--' in bot_cmds: bot_cmds.remove('--')
    if not bot_cmds:
        print("Please provide the launch command string for at least one bot.\nUse the --help flag for usage details.")
        sys.exit(1)

    width, height = map(int, args.dimensions.split())
    seed = args.seed if args.seed is not None else int(time.time())
    random.seed(seed)

    num_players = len(bot_cmds)
    if args.nplayers is not None: num_players = args.nplayers

    productions = [[random.randint(1, 15) for _ in range(width)] for _ in range(height)]
    strengths = [[random.randint(0, 255) for _ in range(width)] for _ in range(height)]
    owners = [[0 for _ in range(width)] for _ in range(height)]

    start_positions = [(0, 0), (height-1, width-1), (0, width-1), (height-1, 0), (height//2, width//2), (height//2, 0)]
    for i in range(num_players):
        y, x = start_positions[i % len(start_positions)]
        owners[y][x] = i + 1
        strengths[y][x] = 255

    bots = []
    for i in range(min(num_players, len(bot_cmds))):
        bots.append(Bot(bot_cmds[i], i+1))
        if not args.quiet: print(bot_cmds[i])

    if not args.quiet:
        print(f"{width} {height}")
        for i in range(len(bots)):
            print(f"Init Message sent to player {i+1}.")

    prod_str = " ".join(str(productions[y][x]) for y in range(height) for x in range(width)) + " \n"
    init_map_str = rle_encode([owners[y][x] for y in range(height) for x in range(width)]) + " ".join(str(strengths[y][x]) for y in range(height) for x in range(width)) + " \n"

    for i, b in enumerate(bots):
        b.send(f"{i+1}\n")
        b.send(f"{width} {height} \n")
        b.send(prod_str)
        b.send(init_map_str)
        name = b.get_line(2.0 if not args.timeout else 1000.0).strip()
        if not b.alive:
            b.name = f"Bot #{b.idx}; timed out during Init"
            if not args.quiet: print(f"Bot #{b.idx} timeout or error (Unix) 0")
        else:
            b.name = name
            if not args.quiet: print(f"Init Message received from player {i+1}, {name}.")

    frames = []
    moves_history = []
    num_frames = 0
    max_turns = int(10 * ((width * height) ** 0.5))
    if max_turns > 1000: max_turns = 1000

    def get_frame():
        return [[[owners[y][x], strengths[y][x]] for x in range(width)] for y in range(height)]

    frames.append(get_frame())

    # Game Loop
    for turn in range(max_turns):
        alive_players = [b.idx for b in bots if b.alive]
        players_with_pieces = set(owners[y][x] for y in range(height) for x in range(width) if owners[y][x] > 0)
        for b in bots:
            if b.alive and b.idx not in players_with_pieces:
                b.alive = False

        alive_players = [b.idx for b in bots if b.alive]
        if len(alive_players) <= 1 and num_players > 1: break
        if len(alive_players) == 0: break

        num_frames += 1
        if not args.quiet: print(f"Turn {num_frames}")

        map_str = rle_encode([owners[y][x] for y in range(height) for x in range(width)]) + " ".join(str(strengths[y][x]) for y in range(height) for x in range(width)) + " \n"

        moves = [[0 for _ in range(width)] for _ in range(height)]
        for b in bots:
            if b.alive:
                b.send(map_str)
                line = b.get_line(1.0 if not args.timeout else 1000.0)
                if not b.alive:
                    if not args.quiet: print(f"Bot #{b.idx} timeout or error (Unix) 0")
                    for y in range(height):
                        for x in range(width):
                            if owners[y][x] == b.idx: owners[y][x] = 0
                else:
                    m = parse_moves(line, width, height)
                    for y in range(height):
                        for x in range(width):
                            if owners[y][x] == b.idx:
                                moves[y][x] = m[y][x]

        moves_history.append(moves)

        forces = [[{} for _ in range(width)] for _ in range(height)]
        for y in range(height):
            for x in range(width):
                o = owners[y][x]
                if o == 0:
                    forces[y][x][0] = forces[y][x].get(0, 0) + strengths[y][x]
                else:
                    forces[y][x][o] = forces[y][x].get(o, 0) # Base 0-strength piece left behind
                    d = moves[y][x]
                    if d == 0:
                        forces[y][x][o] += min(255, strengths[y][x] + productions[y][x])
                    else:
                        dx, dy = x, y
                        if d == 1: dy = (y - 1) % height
                        elif d == 2: dx = (x + 1) % width
                        elif d == 3: dy = (y + 1) % height
                        elif d == 4: dx = (x - 1) % width
                        forces[dy][dx][o] = forces[dy][dx].get(o, 0) + strengths[y][x]

        for y in range(height):
            for x in range(width):
                for p in forces[y][x]:
                    forces[y][x][p] = min(255, forces[y][x][p])

        damage = [[{} for _ in range(width)] for _ in range(height)]
        for y in range(height):
            for x in range(width):
                for p, f in forces[y][x].items():
                    if p == 0:
                        for ep in forces[y][x]:
                            if ep != 0: damage[y][x][ep] = damage[y][x].get(ep, 0) + f
                    else:
                        for ep in forces[y][x]:
                            if ep != p: damage[y][x][ep] = damage[y][x].get(ep, 0) + f
                        for (ny, nx) in [((y-1)%height, x), ((y+1)%height, x), (y, (x-1)%width), (y, (x+1)%width)]:
                            for ep in forces[ny][nx]:
                                if ep != p and ep != 0:
