import sys, os, time, json, random, subprocess, threading, argparse

def rle_encode(owners):
    res = []
    if not owners: return ""
    count = 1
    curr = owners[0]
    for i in range(1, len(owners)):
        if owners[i] == curr:
            count += 1
        else:
            res.extend([str(count), str(curr)])
            curr = owners[i]
            count = 1
    res.extend([str(count), str(curr)])
    return " ".join(res) + " "

def parse_moves(line, width, height):
    moves = [[0 for _ in range(width)] for _ in range(height)]
    parts = line.strip().split()
    i = 0
    while i < len(parts):
        try:
            x = int(parts[i])
            y = int(parts[i+1])
            d = int(parts[i+2])
            if 0 <= x < width and 0 <= y < height and 0 <= d <= 4:
                moves[y][x] = d
            i += 3
        except:
            break
    return moves

