    def __init__(self, cmd, idx):
        self.cmd = cmd
        self.idx = idx
        self.process = subprocess.Popen(cmd, shell=True, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, bufsize=1)
        self.name = f"Bot #{idx}"
        self.alive = True
        self.timeout = False
        self.rank = 0
        self.last_alive = -1
        self.errored = False
        self.error_frame = -1

    def send(self, msg):
        if not self.alive: return
        try:
            self.process.stdin.write(msg)
            self.process.stdin.flush()
        except:
            self.alive = False
            self.errored = True

    def get_line(self, t):
        if not self.alive: return ""
        res = [""]
        def read():
