        if b.errored:
            with open(os.path.join(args.replaydirectory, f"{b.idx}-{ts}.log"), "w") as f:
                f.write(f" --- Init ---\n{b.name}\n --- Bot used 0 milliseconds ---\n-----------------------------------------------------------------------------\n --- Frame #{b.error_frame} ---\n\nERRORED!\nNo response received.\n")

if __name__ == "__main__":
    main()
